use super::*;
use context::*;
use std::sync::atomic::{AtomicBool,Ordering};
fn map(labels:Vec<u32>,w:u32,h:u32)->LabelMap{LabelMap{width:w,height:h,labels,paints:vec![crate::ir::Paint::Solid(crate::Color::new(255,0,0)),crate::ir::Paint::Solid(crate::Color::new(0,0,255))]}}
fn output_text(p:&[(u32,MultiPath)])->String{format!("{:?}",p)}
#[test]fn contextual_topology_legacy_order_work_capacity_parity(){
 for m in [map(vec![0;16],4,4),map(vec![0,1,1,0],2,2),map(vec![0,0,1,0,1,1,0,0,1],3,3),map(vec![0,0,0,0,1,0,0,0,0],3,3)]{
  let token=AtomicBool::new(false);let map_bytes=m.labels.capacity()*4+m.paints.capacity()*std::mem::size_of::<crate::ir::Paint>();let retained=map_bytes+4096;let ctx=PipelineContext::new(retained,256*1024*1024,10000000,&token).unwrap();
  let old=PreparedTopology::prepare(&m,TopologyBudget::default()).unwrap();let new=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&ctx).unwrap();assert_eq!(format!("{:?}",old.graph().segments),format!("{:?}",new.graph().segments));assert_eq!(format!("{:?}",old.faces()),format!("{:?}",new.faces()));assert_eq!(format!("{:?}",old.incidence()),format!("{:?}",new.incidence()));assert_eq!(new.preparation_bytes,old.preparation_bytes);
  let cache=new.graph().segments.iter().map(|s|s.points.clone()).collect::<Vec<_>>();let cache_bytes=cache.capacity()*std::mem::size_of::<Vec<PointI32>>()+cache.iter().map(|p|p.capacity()*std::mem::size_of::<PointI32>()).sum::<usize>();ctx.charge(cache_bytes).unwrap();let prior=ctx.work.used.get();let expected=old.compose_integer_polylines(&cache).unwrap();let actual=new.compose_integer_polylines_with_context(&cache,&ctx).unwrap();assert_eq!(output_text(&expected),output_text(&actual));assert!(ctx.work.used.get()>prior);let output_bytes=actual.capacity()*std::mem::size_of::<(u32,MultiPath)>()+actual.iter().map(|(_,p)|p.subpaths.capacity()*std::mem::size_of::<crate::ir::SubPath>()+p.subpaths.iter().map(|s|s.commands.capacity()*std::mem::size_of::<PathCmd>()).sum::<usize>()).sum::<usize>();let graph_bytes=new.preparation_bytes-map_bytes;assert_eq!(ctx.capacity.live.get(),retained+graph_bytes+cache_bytes+output_bytes);println!("context pixels={} edges={} chains={} prepwork={} totalwork={} globalpeak={} localpreppeak={} live={} categories={:?}",m.labels.len(),new.boundary_edges,cache.len(),prior,ctx.work.used.get(),ctx.capacity.peak.get(),new.preparation_peak_bytes(),ctx.capacity.live.get(),ctx.work.categories.each_ref().map(|n|n.get()));drop(actual);ctx.release_after_drop(output_bytes).unwrap();drop(cache);ctx.release_after_drop(cache_bytes).unwrap();drop(new);ctx.release_after_drop(graph_bytes).unwrap();assert_eq!(ctx.capacity.live.get(),retained);
 }
}
#[test]fn each_context_phase_cancellation_and_persistent_compose_boundaries(){
 let m=map(vec![0,1,1,0],2,2);let bytes=m.labels.capacity()*4+m.paints.capacity()*std::mem::size_of::<crate::ir::Paint>();
 for kind in [Action::Grid,Action::Walk,Action::Component,Action::Contour,Action::Incidence,Action::Sort,Action::Allocation,Action::Initialization,Action::Write]{let flag=AtomicBool::new(false);let ctx=PipelineContext::new(bytes,1000000,1000000,&flag).unwrap();context::inject(kind,1);assert!(matches!(PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&ctx),Err(TopologyError::Cancelled)),"{kind:?}");context::clear();}
 let flag=AtomicBool::new(false);let ctx=PipelineContext::new(bytes,1000000,1000000,&flag).unwrap();let t=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&ctx).unwrap();let cache=t.graph().segments.iter().map(|s|s.points.clone()).collect::<Vec<_>>();let backing=cache.capacity()*std::mem::size_of::<Vec<PointI32>>()+cache.iter().map(|p|p.capacity()*std::mem::size_of::<PointI32>()).sum::<usize>();ctx.charge(backing).unwrap();context::inject(Action::Compose,4);assert!(matches!(t.compose_integer_polylines_with_context(&cache,&ctx),Err(TopologyError::Cancelled)));context::clear();
 // Replay the entire same context, not a fresh compose account.
 let run=|limit:usize|{let f=AtomicBool::new(false);let c=PipelineContext::new(bytes,1000000,limit,&f).unwrap();let t=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&c)?;let cache=t.graph().segments.iter().map(|s|s.points.clone()).collect::<Vec<_>>();let n=cache.capacity()*std::mem::size_of::<Vec<PointI32>>()+cache.iter().map(|p|p.capacity()*std::mem::size_of::<PointI32>()).sum::<usize>();c.charge(n)?;let _out=t.compose_integer_polylines_with_context(&cache,&c)?;Ok::<usize,TopologyError>(c.work.used.get())};let total=run(1000000).unwrap();assert_eq!(run(total),Ok(total));assert!(matches!(run(total-1),Err(TopologyError::WorkLimitExceeded)));
}
#[test]fn legacy_budget_local_peak_and_terminal_failure_contract(){let m=map(vec![0,1,1,0],2,2);let flag=AtomicBool::new(false);let bytes=m.labels.capacity()*4+m.paints.capacity()*std::mem::size_of::<crate::ir::Paint>();let old=PreparedTopology::prepare(&m,TopologyBudget::default()).unwrap();let ctx=PipelineContext::new(bytes+4096,1000000,1000000,&flag).unwrap();ctx.charge(500000).unwrap();ctx.release_after_drop(500000).unwrap();let local=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&ctx).unwrap();assert_eq!(local.preparation_peak_bytes(),old.preparation_peak_bytes());assert!(ctx.capacity.peak.get()>local.preparation_peak_bytes());let b=TopologyBudget{max_estimated_bytes:old.preparation_peak_bytes()-1,..TopologyBudget::default()};let c=PipelineContext::new(bytes,1000000,1000000,&flag).unwrap();assert!(matches!(PreparedTopology::prepare_with_context(&m,b,&c),Err(TopologyError::EstimatedBytesLimitExceeded)));assert!(matches!(c.action(Action::Grid),Err(TopologyError::CountMismatch)));assert!(matches!(PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&c),Err(TopologyError::CountMismatch)));let c=PipelineContext::new(bytes,bytes,1000000,&flag).unwrap();assert!(matches!(c.charge(1),Err(TopologyError::EstimatedBytesLimitExceeded)));assert!(matches!(c.action(Action::Grid),Err(TopologyError::CountMismatch)));let c=PipelineContext::new(bytes,1000000,0,&flag).unwrap();assert!(matches!(c.action(Action::Grid),Err(TopologyError::WorkLimitExceeded)));assert!(matches!(c.charge(0),Err(TopologyError::CountMismatch)));}
#[test]fn direct_arithmetic_and_release_failures_poison_context(){let flag=AtomicBool::new(false);let c=PipelineContext::new(0,usize::MAX,usize::MAX,&flag).unwrap();c.work.used.set(usize::MAX);assert_eq!(c.action(Action::Grid),Err(TopologyError::ArithmeticOverflow));assert_eq!(c.charge(0),Err(TopologyError::CountMismatch));let c=PipelineContext::new(0,usize::MAX,usize::MAX,&flag).unwrap();c.capacity.live.set(usize::MAX);assert_eq!(c.charge(1),Err(TopologyError::ArithmeticOverflow));assert_eq!(c.action(Action::Grid),Err(TopologyError::CountMismatch));let c=PipelineContext::new(10,100,100,&flag).unwrap();assert_eq!(c.release_after_drop(1),Err(TopologyError::CountMismatch));assert_eq!(c.charge(0),Err(TopologyError::CountMismatch));let c=PipelineContext::new(0,100,100,&flag).unwrap();assert_eq!(c.release_after_drop(1),Err(TopologyError::ArithmeticOverflow));assert_eq!(c.action(Action::Grid),Err(TopologyError::CountMismatch));}
#[test]fn provisional_work_capacity_minusone_and_cancellation(){let m=map(vec![0,1,1,0],2,2);let token=AtomicBool::new(false);let bytes=m.labels.capacity()*4+m.paints.capacity()*std::mem::size_of::<crate::ir::Paint>();let ctx=PipelineContext::new(bytes,1000000,1000000,&token).unwrap();let _=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&ctx).unwrap();let work=ctx.work.used.get();let peak=ctx.capacity.peak.get();for n in [work-1,work]{let c=PipelineContext::new(bytes,1000000,n,&token).unwrap();let result=PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&c);if n<work{assert!(matches!(result,Err(TopologyError::WorkLimitExceeded)))}else{assert!(result.is_ok())}}let c=PipelineContext::new(bytes,peak-1,1000000,&token).unwrap();assert!(matches!(PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&c),Err(TopologyError::EstimatedBytesLimitExceeded)));token.store(true,Ordering::Release);let c=PipelineContext::new(bytes,1000000,1000000,&token).unwrap();assert!(matches!(PreparedTopology::prepare_with_context(&m,TopologyBudget::default(),&c),Err(TopologyError::Cancelled)));}
